<script setup>
import {ref,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {useRoute} from 'vue-router';
import {api} from '../api.js';
import {subscribe} from '../realtime.js';
const id=useRoute().params.id,event=ref(null),messages=ref([]),text=ref(''),error=ref(''),busy=ref(false),box=ref(null);
let cursor=0,loading=false,queued=false,stop,timer,live=false,closed=false;
async function load(){if(loading){queued=true;return;}loading=true;try{let more=true;while(more&&!closed){const r=await api(`/api/events/${id}/messages?after=${cursor}`);if(closed)return;event.value=r.event;const known=new Map(messages.value.map(m=>[String(m.id),m]));r.messages.forEach(m=>known.set(String(m.id),m));messages.value=[...known.values()].sort((a,b)=>Number(a.id)-Number(b.id));const next=Number(r.cursor||cursor);more=r.hasMore&&next>cursor;cursor=next;}error.value='';await nextTick();box.value?.scrollTo({top:box.value.scrollHeight});}catch(e){error.value=e.message;if([403,404].includes(e.status)){event.value=null;messages.value=[];stop?.();clearInterval(timer);}}finally{loading=false;if(queued&&!closed){queued=false;load();}}}
async function send(){if(!text.value.trim()||busy.value)return;busy.value=true;try{await api(`/api/events/${id}/messages`,{method:'POST',body:{body:text.value.trim()}});text.value='';await load();}catch(e){error.value=e.message;}finally{busy.value=false;}}
onMounted(()=>{load();stop=subscribe(`event:${id}`,load,state=>live=state);timer=setInterval(()=>{if(!live&&document.visibilityState==='visible')load();},15000);});
onBeforeUnmount(()=>{closed=true;stop?.();clearInterval(timer);});
</script>
<template><div class="session-chat"><div class="row"><RouterLink class="btn ghost sm" to="/app/events" aria-label="Back to sessions">←</RouterLink><h1>{{ event?.title||'Session chat' }}</h1></div><p v-if="error" class="err" role="alert">{{ error }}</p><div ref="box" class="messages" aria-live="polite"><p v-if="event&&!messages.length" class="mute">Start the conversation.</p><div v-for="m in messages" :key="m.id" class="message" :class="{mine:m.mine}"><b v-if="!m.mine">{{ m.name }}</b><p>{{ m.body }}</p><time>{{ new Date(m.createdAt).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}) }}</time></div></div><form v-if="event" class="row" @submit.prevent="send"><input v-model="text" maxlength="2000" placeholder="Message the group" aria-label="Message the group" class="grow" :disabled="busy"><button class="btn sm" :disabled="busy||!text.trim()">Send</button></form></div></template>
<style scoped>.session-chat{display:flex;flex-direction:column;height:calc(100dvh - 180px);min-height:350px}h1{font-size:23px}.messages{overflow:auto;flex:1;margin:16px 0}.message{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:10px 14px;max-width:85%;width:fit-content;margin-bottom:8px;overflow-wrap:anywhere}.message.mine{margin-left:auto;background:var(--soft)}.message b{font-size:12px}.message p{margin:2px 0;white-space:pre-wrap}.message time{font-size:11px;color:var(--mute)}form input{min-width:0;width:0;flex:1}</style>
